"""Emit synthetic JSON lines for the Kafka to Log Analytics demo."""
import argparse
from dataclasses import dataclass
from datetime import datetime, timezone
from decimal import Decimal, InvalidOperation, ROUND_FLOOR
import json
import math
import sys
import time
import uuid


def non_negative(value):
    number = int(value)
    if number < 0:
        raise argparse.ArgumentTypeError("must be non-negative")
    return number


def positive_decimal(value):
    try:
        number = Decimal(value)
    except InvalidOperation:
        raise argparse.ArgumentTypeError("must be a positive finite number")
    if not number.is_finite() or number <= 0:
        raise argparse.ArgumentTypeError("must be a positive finite number")
    return number


@dataclass(frozen=True)
class GenerationPlan:
    count: int
    interval_seconds: float
    duration_seconds: float | None
    events_per_minute: float | None


def add_timing_arguments(parser):
    parser.add_argument("--count", type=non_negative, default=None,
                        help="Total events; defaults to 100 when no timing settings are supplied")
    parser.add_argument("--events-per-minute", type=positive_decimal,
                        help="Target generation rate; combine with duration or count")
    duration = parser.add_mutually_exclusive_group()
    duration.add_argument("--duration-minutes", type=positive_decimal)
    duration.add_argument("--duration-seconds", type=positive_decimal)
    parser.add_argument("--interval-ms", type=non_negative, default=0,
                        help="Legacy pacing for count mode; cannot be combined with rate or duration")


def generation_plan(args):
    count, rate = args.count, args.events_per_minute
    duration = args.duration_seconds
    if args.duration_minutes is not None:
        duration = args.duration_minutes * 60
    if args.interval_ms and (rate is not None or duration is not None):
        raise ValueError("use interval-ms with count only, or choose rate/duration pacing")
    if count is not None and rate is not None and duration is not None:
        raise ValueError("specify any two of count, events-per-minute and duration; the third is derived")
    if rate is None and duration is None:
        count = 100 if count is None else count
        interval = args.interval_ms / 1000
        return GenerationPlan(count, interval, count * interval if interval else None,
                              60 / interval if interval else None)
    if count is None and (rate is None or duration is None):
        raise ValueError("provide rate and duration, count and duration, or count and rate")
    if count is not None and count <= 0:
        raise ValueError("count must be positive for a timed run")
    if count is None:
        count = int((rate * duration / 60).to_integral_value(rounding=ROUND_FLOOR))
        if count < 1:
            raise ValueError("rate and duration produce zero whole events; increase one of them")
    if rate is None:
        rate = Decimal(count) * 60 / duration
    interval = Decimal(60) / rate
    if duration is None:
        duration = Decimal(count) * interval
    interval_float, duration_float, rate_float = float(interval), float(duration), float(rate)
    if not all(math.isfinite(value) and value > 0
               for value in [interval_float, duration_float, rate_float]):
        raise ValueError("rate or duration is outside the supported finite range")
    return GenerationPlan(count, interval_float, duration_float, rate_float)


def wait_until(deadline):
    remaining = deadline - time.monotonic()
    if remaining > 0:
        time.sleep(remaining)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    add_timing_arguments(parser)
    parser.add_argument("--run-id", default="run-" + uuid.uuid4().hex[:12])
    parser.add_argument("--mode", choices=["normal", "error-spike", "edge-cases"], default="normal")
    parser.add_argument("--message-bytes", type=non_negative, default=0,
                        help="Minimum ASCII message length; use 16000 to demonstrate byte chunking")
    args = parser.parse_args()
    try:
        plan = generation_plan(args)
    except ValueError as error:
        parser.error(str(error))
    print(f"demo_run_id={args.run_id} planned_count={plan.count} "
          f"target_events_per_minute={plan.events_per_minute} "
          f"target_duration_seconds={plan.duration_seconds}", file=sys.stderr)
    started = time.monotonic()
    for index in range(plan.count):
        if plan.interval_seconds:
            wait_until(started + index * plan.interval_seconds)
        if index % (2 if args.mode == "error-spike" else 20) == 0:
            level = "ERROR"
        elif index % 5 == 0:
            level = "WARN"
        else:
            level = "INFO"
        message = {"ERROR": "Payment request failed", "WARN": "Request took longer than expected",
                   "INFO": "Request completed"}[level]
        if args.mode == "edge-cases":
            message = ['Quoted message: "payment failed"', r'Path C:\logs\checkout.log',
                       'Unicode: नमस्ते café 日本語 🚀', 'First line\nSecond line\tTabbed',
                       'JSON text: {"status":"ok"}'][index % 5]
        message = message.ljust(args.message_bytes, "x")
        event = {
            "timestamp": datetime.now(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z"),
            "demo_run_id": args.run_id,
            "event_id": f"{args.run_id}-{index:06d}",
            "service": ["checkout", "inventory", "payments"][index % 3],
            "level": level,
            "message": message,
            "latency_ms": 850 if level == "ERROR" else 25 + index % 50,
        }
        print(json.dumps(event, ensure_ascii=False, separators=(",", ":")), flush=True)
    if plan.duration_seconds is not None:
        wait_until(started + plan.duration_seconds)
    print(f"generated={plan.count} elapsed_seconds={time.monotonic() - started:.3f}", file=sys.stderr)


if __name__ == "__main__":
    try:
        main()
    except BrokenPipeError:
        sys.exit(1)
